"""Capture tcp dump traffic"""
from __future__ import absolute_import, division, print_function, \
    unicode_literals
import os
from taf.ul.trs_e2e_fw.lib.utils import replace_with_builtin_and_admin_values
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.interface import tcpdump
from taf.ul.trs_e2e_fw.lib.traffic.capture.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from future import standard_library

standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class TcpdumpCapture(ToolBase):
    """Capture tcp dump traffic"""
    TOOL = "tcpdump"

    def __init__(self, config, capture_device):
        self.config = config
        self.tcpdump = tcpdump()
        self.log_dir = '/tmp'
        self.capture_device = capture_device

    def traffic_capture_start(self, **kwargs):
        """Starts the traffic capture"""
        alias = kwargs.pop("alias", "default")
        capture_filter = kwargs.pop("capture_filter", "")
        capture_device_params = get_config_variable(['traffic_capture', self.capture_device])
        interface = get_config_variable(['traffic_capture', self.capture_device,
                                         'capture_interface'])
        ssh_prompt = get_config_variable(['traffic_capture', self.capture_device, 'ssh_prompt'])
        ip = get_config_variable(['traffic_capture', self.capture_device, 'ip'])
        user = get_config_variable(['traffic_capture', self.capture_device, 'user'])
        password = get_config_variable(['traffic_capture', self.capture_device, 'password'])
        capture_port = get_config_variable(['traffic_capture', self.capture_device,
                                            'capture_port'])
        remote_lmp_ip = get_config_variable(['traffic_capture', self.capture_device,
                                             'remote_lmp_ip'])
        sudo = get_config_variable(['traffic_capture', self.capture_device, 'sudo']) or 'false'
        if sudo.lower() == 'true':
            sudo = True
        else:
            sudo = False
        logger.debug("Setting up tcpdump....")
        if capture_device_params.get('config_name'):
            tcpdump_dir = get_config_variable(['traffic_capture', self.capture_device, 'tcpdump_dir'])
            log_dir = get_config_variable(['traffic_capture', self.capture_device, 'log_dir'])
            if capture_device_params.get('fhnet_cap_only') is not None:
                self.tcpdump.setup_tcpdump(interface, log_dir=log_dir, alias=alias,
                                           config_name=capture_device_params['config_name'],
                                           tcpdump_dir=tcpdump_dir,
                                           fhnet_login_only=capture_device_params['fhnet_cap_only'])
            else:
                self.tcpdump.setup_tcpdump(interface, log_dir=log_dir, alias=alias,
                                           config_name=capture_device_params['config_name'],
                                           hop_list=capture_device_params['hop_list'],
                                           tcpdump_dir=tcpdump_dir)
        elif remote_lmp_ip is None:
            self.tcpdump.setup_tcpdump(interface, log_dir=self.log_dir, ssh_ip=ip, ssh_username=user,
                                       ssh_password=password, ssh_port=capture_port, ssh_prompt=ssh_prompt, sudo=sudo,
                                       alias=alias)
        else:
            remote_lmp_ip = get_config_variable(['traffic_capture', self.capture_device,
                                                 'remote_lmp_ip'])
            remote_lmp_user = get_config_variable(['traffic_capture', self.capture_device,
                                                   'remote_lmp_user'])
            remote_lmp_password = get_config_variable(['traffic_capture', self.capture_device,
                                                       'remote_lmp_password'])
            self.tcpdump.setup_tcpdump(interface, log_dir=self.log_dir, ssh_ip=ip, ssh_username=user,
                                       ssh_password=password, ssh_port=capture_port, ssh_prompt=ssh_prompt, alias=alias,
                                       remote_lmp_ip=remote_lmp_ip, remote_lmp_user=remote_lmp_user,
                                       remote_lmp_password=remote_lmp_password, sudo=sudo)
        if not capture_filter == "":
            capture_filter = replace_with_builtin_and_admin_values.replace(capture_filter)
            # capture_filter = _format_capture_filter(capture_filter)
        logger.debug("starting tcpdump capture....")
        if capture_device_params.get('hop_list'):
            self.tcpdump.start_capturing(capture_filter, alias=alias, sudo=True)
        else:
            self.tcpdump.start_capturing(capture_filter, alias=alias, sudo=sudo)

    def traffic_capture_stop(self, **kwargs):
        """Stops the traffic capture"""
        alias = kwargs.pop("alias", "default")
        dest_file = 'execution_logs/{}_{}.pcap'.format(alias, get_config_variable(["bts_id"]))
        if not os.path.exists(os.path.dirname(dest_file)):
            os.makedirs(os.path.dirname(dest_file))
        ip = get_config_variable(['traffic_capture', self.capture_device, 'ip'])
        user = get_config_variable(['traffic_capture', self.capture_device, 'user'])
        password = get_config_variable(['traffic_capture', self.capture_device, 'password'])
        capture_device_params = get_config_variable(['traffic_capture', self.capture_device])
        logger.debug("stopping capture...")
        self.tcpdump.stop_capturing(alias=alias)
        logger.debug("downloading pcap....")

        if capture_device_params.get('hop_list'):
            dest = 'oam-0.local:/tmp/'
            self.tcpdump.download_pcap_file(dest, alias=alias, sudo=True)

        output = self.tcpdump.download_pcap_file(dest_file, alias=alias)
        remote_pcap_path, destination = output[0]
        logger.debug("pcap download remote path {}, destination {}".format(remote_pcap_path,
                                                                           destination))
        # cmd = "rm -rf {0}/*.pcap".format(self.log_dir)
        cmd = "rm -f {0}".format(remote_pcap_path)
        Communicator().execute_command_remotely(ip, user, password, cmd)
        logger.debug("performing tcpdump  teardown...")
        self.tcpdump.teardown_tcpdump(alias=alias)
        # print "type of dest file", type(destination)
        return destination
